import { useEffect, useState } from 'react';
import { ApiError } from './api.ts';
import { Loading } from './Overview.tsx';

type State =
  | { kind: 'loading' }
  | { kind: 'report'; html: string }
  | { kind: 'unprovisioned' }
  | { kind: 'empty' }
  | { kind: 'error'; message: string };

/** Latest CI test report (#24).
 *
 *  Served as raw HTML from KV, so it is rendered in a sandboxed iframe rather
 *  than injected into this document. The report is generated by CI, but it
 *  embeds test names, file paths and failure output — treating that as trusted
 *  markup in the admin origin would make any string that reaches a test title an
 *  XSS vector against the console. `sandbox` with no `allow-same-origin` keeps it
 *  inert and unable to touch admin cookies. */
export function CiReport() {
  const [state, setState] = useState<State>({ kind: 'loading' });

  useEffect(() => {
    fetch('/api/ci/test-report', { credentials: 'include' })
      .then(async (res) => {
        if (res.status === 503) return setState({ kind: 'unprovisioned' });
        if (res.status === 404) return setState({ kind: 'empty' });
        if (!res.ok) {
          const body = await res.json().catch(() => ({}) as { error?: string });
          throw new ApiError(
            res.status,
            (body as { error?: string }).error ?? `HTTP ${res.status}`,
          );
        }
        setState({ kind: 'report', html: await res.text() });
      })
      .catch((e) => setState({ kind: 'error', message: (e as Error).message }));
  }, []);

  if (state.kind === 'loading') return <Loading />;

  return (
    <div>
      <h1 className="text-xl font-bold mb-1 text-ink">CI test report</h1>
      <p className="text-sm mb-4 text-muted">
        The most recent report uploaded by CI. Rendered sandboxed — it is generated output, not
        trusted markup.
      </p>

      {state.kind === 'unprovisioned' && (
        <Notice tone="text-warning" title="Not provisioned yet">
          The <code>CI_KV</code> namespace is not bound, so there is nowhere to store a report.
          Create it with <code>wrangler kv namespace create fgs-admin-kv</code>, uncomment the
          binding in <code>apps/admin/wrangler.toml</code>, and set <code>CI_TOKEN</code> so CI can
          upload.
        </Notice>
      )}

      {state.kind === 'empty' && (
        <Notice tone="text-muted" title="No report uploaded yet">
          KV is bound but empty — CI has not yet <code>PUT /api/ci/test-report</code>.
        </Notice>
      )}

      {state.kind === 'error' && (
        <Notice tone="text-danger" title="Could not load the report">
          {state.message}
        </Notice>
      )}

      {state.kind === 'report' && (
        <iframe
          title="CI test report"
          sandbox=""
          srcDoc={state.html}
          className="w-full rounded-xl border border-line bg-white h-[75vh]"
        />
      )}
    </div>
  );
}

function Notice({
  tone,
  title,
  children,
}: {
  tone: string;
  title: string;
  children: React.ReactNode;
}) {
  return (
    <div className="rounded-xl border border-line bg-panel p-4">
      <div className={`text-sm font-semibold mb-1 ${tone}`}>{title}</div>
      <div className="text-sm text-muted">{children}</div>
    </div>
  );
}
